begin;
with j as (select * from jsonb_to_recordset($law7d0026$[{"code_id":"GK_RF","article_number":"376","version_date":"1994-11-30","article_text":"1. Гарант отказывает бенефициару в удовлетворении его требования, если это требование или приложенные к нему документы не соответствуют условиям независимой гарантии либо представлены гаранту по окончании срока действия независимой гарантии. Гарант должен уведомить об этом бенефициара в срок, предусмотренный пунктом 2 статьи 375 настоящего Кодекса, указав причину отказа.\n\n2. Гарант имеет право приостановить платеж на срок до семи дней, если он имеет разумные основания полагать, что:\n\n1) какой-либо из представленных ему документов является недостоверным;\n\n2) обстоятельство, на случай возникновения которого независимая гарантия обеспечивала интересы бенефициара, не возникло;\n\n3) основное обязательство принципала, обеспеченное независимой гарантией, недействительно;\n\n4) исполнение по основному обязательству принципала принято бенефициаром без каких-либо возражений.\n\n3. В случае приостановления платежа гарант обязан уведомить бенефициара и принципала о причинах и сроке приостановления платежа незамедлительно.\n\n4. Гарант несет ответственность перед бенефициаром и принципалом за необоснованное приостановление платежа.\n\n5. По истечении срока, предусмотренного пунктом 2 настоящей статьи, при отсутствии оснований для отказа в удовлетворении требования бенефициара (пункт 1 настоящей статьи) гарант обязан произвести платеж по гарантии.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 376. Отказ гаранта удовлетворить требование бенефициара","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b06f970751f521d04be9c7d9fd53c0790336d7c06726612274e835be5cef59b3"},{"code_id":"GK_RF","article_number":"378","version_date":"1994-11-30","article_text":"1. Обязательство гаранта перед бенефициаром по независимой гарантии прекращается:\n\n1) уплатой бенефициару суммы, на которую выдана независимая гарантия;\n\n2) окончанием определенного в независимой гарантии срока, на который она выдана;\n\n3) вследствие отказа бенефициара от своих прав по гарантии;\n\n4) по соглашению гаранта с бенефициаром о прекращении этого обязательства.\n\n2. Независимой гарантией или соглашением гаранта с бенефициаром может быть предусмотрено, что для прекращения обязательства гаранта перед бенефициаром необходимо возвратить гаранту выданную им гарантию.\n\nПрекращение обязательства гаранта по основаниям, указанным в подпунктах 1 и 2 пункта 1 настоящей статьи, не зависит от того, возвращена ли ему независимая гарантия.\n\n3. Гарант, которому стало известно о прекращении независимой гарантии по основаниям, предусмотренным настоящей статьей, должен уведомить об этом принципала без промедления.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 378. Прекращение независимой гарантии","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7ddd8b00818e9f1ab91e57a5e927acbd07f04f7f15e92c94cde4816540d4c49c"},{"code_id":"GK_RF","article_number":"379","version_date":"1994-11-30","article_text":"1. Принципал обязан возместить гаранту выплаченные в соответствии с условиями независимой гарантии денежные суммы, если соглашением о выдаче гарантии не предусмотрено иное.\n\n2. Гарант не вправе требовать от принципала возмещения денежных сумм, уплаченных бенефициару не в соответствии с условиями независимой гарантии или за нарушение обязательства гаранта перед бенефициаром, за исключением случаев, если соглашением гаранта с принципалом предусмотрено иное либо принципал дал согласие на платеж по гарантии.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 379. Возмещение гаранту сумм, выплаченных по независимой гарантии","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d56d970ac3733b7297621e0906a18a69da8de4384fb59a1a35b035798e1c430f"},{"code_id":"GK_RF","article_number":"38","version_date":"1994-11-30","article_text":"1. При необходимости постоянного управления недвижимым и ценным движимым имуществом подопечного орган опеки и попечительства заключает с управляющим, определенным этим органом, договор о доверительном управлении таким имуществом. В этом случае опекун или попечитель сохраняет свои полномочия в отношении того имущества подопечного, которое не передано в доверительное управление.\n\nПри осуществлении управляющим правомочий по управлению имуществом подопечного на управляющего распространяется действие правил, предусмотренных пунктами 2 и 3 статьи 37 настоящего Кодекса.\n\n2. Доверительное управление имуществом подопечного прекращается по основаниям, предусмотренным законом для прекращения договора о доверительном управлении имуществом, а также в случаях прекращения опеки и попечительства.","article_title":"Статья 38. Доверительное управление имуществом подопечного","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"36ae01a539f7fd1d3e005021c10cd7738d793c33aca6b5114e4f391e32554ad0"},{"code_id":"GK_RF","article_number":"380","version_date":"1994-11-30","article_text":"1. Задатком признается денежная сумма, выдаваемая одной из договаривающихся сторон в счет причитающихся с нее по договору платежей другой стороне, в доказательство заключения договора и в обеспечение его исполнения.\n\n2. Соглашение о задатке независимо от суммы задатка должно быть совершено в письменной форме.\n\n3. В случае сомнения в отношении того, является ли сумма, уплаченная в счет причитающихся со стороны по договору платежей, задатком, в частности вследствие несоблюдения правила, установленного пунктом 2 настоящей статьи, эта сумма считается уплаченной в качестве аванса, если не доказано иное.","article_title":"Статья 380. Понятие задатка. Форма соглашения о задатке","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"78f25abc9a5347a2e53b20fc72a234bf8505fd2233884bacb1d9aa67e9839135"},{"code_id":"GK_RF","article_number":"381","version_date":"1994-11-30","article_text":"1. При прекращении обязательства до начала его исполнения по соглашению сторон либо вследствие невозможности исполнения (статья 416) задаток должен быть возвращен.\n\n2. Если за неисполнение договора ответственна сторона, давшая задаток, он остается у другой стороны. Если за неисполнение договора ответственна сторона, получившая задаток, она обязана уплатить другой стороне двойную сумму задатка.\n\nСверх того, сторона, ответственная за неисполнение договора, обязана возместить другой стороне убытки с зачетом суммы задатка, если в договоре не предусмотрено иное.\n\n(Дополнение параграфом - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 381. Последствия прекращения и неисполнения обязательства, обеспеченного задатком","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f70de94d35de2e883a2ba71754315eb60b97cc34e724b1211ebd0cbc39afe8f6"},{"code_id":"GK_RF","article_number":"381.1","version_date":"1994-11-30","article_text":"1. Денежное обязательство, в том числе обязанность возместить убытки или уплатить неустойку в случае нарушения договора, и обязательство, возникшее по основаниям, предусмотренным пунктом 2 статьи 1062 настоящего Кодекса, по соглашению сторон могут быть обеспечены внесением одной из сторон в пользу другой стороны определенной денежной суммы (обеспечительный платеж). Обеспечительным платежом может быть обеспечено обязательство, которое возникнет в будущем.\n\nПри наступлении обстоятельств, предусмотренных договором, сумма обеспечительного платежа засчитывается в счет исполнения соответствующего обязательства.\n\n2. В случае ненаступления в предусмотренный договором срок обстоятельств, указанных в абзаце втором пункта 1 настоящей статьи, или прекращения обеспеченного обязательства обеспечительный платеж подлежит возврату, если иное не предусмотрено соглашением сторон.\n\n3. Договором может быть предусмотрена обязанность соответствующей стороны дополнительно внести или частично возвратить обеспечительный платеж при наступлении определенных обстоятельств.\n\n4. На сумму обеспечительного платежа проценты, установленные статьей 3171 настоящего Кодекса, не начисляются, если иное не предусмотрено договором.","article_title":"Статья 381.1. Обеспечительный платеж","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c28a51b4c3b77d0c082f9d9d07a9f23ef3279f523c5e484d80eed704be7b9f4e"},{"code_id":"GK_RF","article_number":"381.2","version_date":"1994-11-30","article_text":"Правила об обеспечительном платеже (статья 3811) применяются также в случаях, если в счет обеспечения вносятся подлежащие передаче по обеспечиваемому обязательству акции, облигации, иные ценные бумаги или вещи, определенные родовыми признаками. Если в счет обеспечения исполнения обязательств вносятся ценные бумаги, особенности обеспечительного платежа могут быть установлены законами о ценных бумагах. (В редакции Федерального закона от 26.07.2017 № 212-ФЗ)\n\n(Параграф в редакции Федерального закона от 21.12.2013 № 367-ФЗ)\n\n1. Общие положения","article_title":"Статья 381.2. Применение правил об обеспечительном платеже","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ab0742021805442bea6a5c9a2331868445b33b473195445f20360bb1ca5aee4a"},{"code_id":"GK_RF","article_number":"382","version_date":"1994-11-30","article_text":"1. Право (требование), принадлежащее на основании обязательства кредитору, может быть передано им другому лицу по сделке (уступка требования) или может перейти к другому лицу на основании закона.\n\n2. Для перехода к другому лицу прав кредитора не требуется согласие должника, если иное не предусмотрено законом или договором.\n\nАбзац. (Утратил силу - Федеральный закон от 26.07.2017 № 212-ФЗ)\n\nПредусмотренный договором запрет перехода прав кредитора к другому лицу не препятствует продаже таких прав в порядке, установленном законодательством об исполнительном производстве и законодательством о несостоятельности (банкротстве).\n\n3. Если должник не был уведомлен в письменной форме о состоявшемся переходе прав кредитора к другому лицу, новый кредитор несет риск вызванных этим неблагоприятных для него последствий. Обязательство должника прекращается его исполнением первоначальному кредитору, произведенным до получения уведомления о переходе права к другому лицу.\n\n4. Первоначальный кредитор и новый кредитор солидарно обязаны возместить должнику - физическому лицу необходимые расходы, вызванные переходом права, в случае, если уступка, которая повлекла такие расходы, была совершена без согласия должника. Иные правила возмещения расходов могут быть предусмотрены в соответствии с законами о ценных бумагах.","article_title":"Статья 382. Основания и порядок перехода прав кредитора к другому лицу","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"94ee0fbcd5d5a832927df22951efa23e0b5c27a03a269fec3e2f5fccd55c3930"},{"code_id":"GK_RF","article_number":"383","version_date":"1994-11-30","article_text":"Переход к другому лицу прав, неразрывно связанных с личностью кредитора, в частности требований об алиментах и о возмещении вреда, причиненного жизни или здоровью, не допускается.","article_title":"Статья 383. Права, которые не могут переходить к другим лицам","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2275e59d74e1c3ca645a88b28c28e771f5ba22c7719945f20adec99e379e30f8"},{"code_id":"GK_RF","article_number":"384","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено законом или договором, право первоначального кредитора переходит к новому кредитору в том объеме и на тех условиях, которые существовали к моменту перехода права. В частности, к новому кредитору переходят права, обеспечивающие исполнение обязательства, а также другие связанные с требованием права, в том числе право на проценты.\n\n2. Право требования по денежному обязательству может перейти к другому лицу в части, если иное не предусмотрено законом.\n\n3. Если иное не предусмотрено законом или договором, право на получение исполнения иного, чем уплата денежной суммы, может перейти к другому лицу в части при условии, что соответствующее обязательство делимо и частичная уступка не делает для должника исполнение его обязательства значительно более обременительным.","article_title":"Статья 384. Объем прав кредитора, переходящих к другому лицу","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f383ef4f8a497cc33a5f6e7e41e3d3a56fa6ac842c51bd90e7d0003fdf7644d6"},{"code_id":"GK_RF","article_number":"385","version_date":"1994-11-30","article_text":"1. Уведомление должника о переходе права имеет для него силу независимо от того, первоначальным или новым кредитором оно направлено.\n\nДолжник вправе не исполнять обязательство новому кредитору до предоставления ему доказательств перехода права к этому кредитору, за исключением случаев, если уведомление о переходе права получено от первоначального кредитора.\n\n2. Если должник получил уведомление об одном или о нескольких последующих переходах права, должник считается исполнившим обязательство надлежащему кредитору при исполнении обязательства в соответствии с уведомлением о последнем из этих переходов права.\n\n3. Кредитор, уступивший требование другому лицу, обязан передать ему документы, удостоверяющие право (требование), и сообщить сведения, имеющие значение для осуществления этого права (требования).","article_title":"Статья 385. Уведомление должника о переходе права","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"86f06c56ec72b0d8474f31a7d4a3fba902487ad0c4858958ef679b4c5e132fb7"},{"code_id":"GK_RF","article_number":"386","version_date":"1994-11-30","article_text":"Должник вправе выдвигать против требования нового кредитора возражения, которые он имел против первоначального кредитора, если основания для таких возражений возникли к моменту получения уведомления о переходе прав по обязательству к новому кредитору. Должник в разумный срок после получения указанного уведомления обязан сообщить новому кредитору о возникновении известных ему оснований для возражений и предоставить ему возможность ознакомления с ними. В противном случае должник не вправе ссылаться на такие основания. (В редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 386. Возражения должника против требования нового кредитора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f483b816e812d2305953b859d1cb18800a34ff8a2343812b74c9df51fd846217"},{"code_id":"GK_RF","article_number":"387","version_date":"1994-11-30","article_text":"1. Права кредитора по обязательству переходят к другому лицу на основании закона при наступлении указанных в нем обстоятельств:\n\n1) в результате универсального правопреемства в правах кредитора;\n\n2) по решению суда о переводе прав кредитора на другое лицо, если возможность такого перевода предусмотрена законом;\n\n3) вследствие исполнения обязательства поручителем должника или не являющимся должником по этому обязательству залогодателем;\n\n4) при суброгации страховщику прав кредитора к должнику, ответственному за наступление страхового случая;\n\n5) в других случаях, предусмотренных законом.\n\n2. К отношениям, связанным с переходом прав на основании закона, применяются правила настоящего Кодекса об уступке требования (статьи 388 - 390), если иное не установлено настоящим Кодексом, другими законами или не вытекает из существа отношений.\n\n3. Уступка требования (цессия)","article_title":"Статья 387. Переход прав кредитора к другому лицу на основании закона","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c238a825b5cad7bf3b37181c702fb637e84613674a96e3210ebcbcbe6a593b3f"},{"code_id":"GK_RF","article_number":"388","version_date":"1994-11-30","article_text":"1. Уступка требования кредитором (цедентом) другому лицу (цессионарию) допускается, если она не противоречит закону.\n\n2. Не допускается без согласия должника уступка требования по обязательству, в котором личность кредитора имеет существенное значение для должника.\n\nСоглашением между должником и цедентом может быть запрещена или ограничена уступка права на получение неденежного исполнения.\n\nЕсли договором был предусмотрен запрет уступки права на получение неденежного исполнения, соглашение об уступке может быть признано недействительным по иску должника только в случае, когда доказано, что другая сторона соглашения знала или должна была знать об указанном запрете. (Дополнение абзацем - Федеральный закон от 26.07.2017 № 212-ФЗ)","article_title":"Статья 388. Условия уступки требования","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"334c3bf9d0587da9c9ef1bf9b647dedaf0b2839b0512dc9f95767b5cd67313bd"},{"code_id":"GK_RF","article_number":"389","version_date":"1994-11-30","article_text":"1. Уступка требования, основанного на сделке, совершенной в простой письменной или нотариальной форме, должна быть совершена в соответствующей письменной форме.\n\n2. Соглашение об уступке требования по сделке, требующей государственной регистрации, должно быть зарегистрировано в порядке, установленном для регистрации этой сделки, если иное не установлено законом.","article_title":"Статья 389. Форма уступки требования","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cf023c0c5d2554e7df818e93edcee9a59cbe7a6e0f0d7b1575a1bb04473f2440"},{"code_id":"GK_RF","article_number":"389.1","version_date":"1994-11-30","article_text":"1. Взаимные права и обязанности цедента и цессионария определяются настоящим Кодексом и договором между ними, на основании которого производится уступка.\n\n2. Требование переходит к цессионарию в момент заключения договора, на основании которого производится уступка, если законом или договором не предусмотрено иное.\n\n3. Если иное не предусмотрено договором, цедент обязан передать цессионарию все полученное от должника в счет уступленного требования.","article_title":"Статья 389.1. Права и обязанности цедента и цессионария","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"060b951330073db598125c5db07f1f79f9e4b2bb1a07cafab57494e2ed3c65bd"},{"code_id":"GK_RF","article_number":"39","version_date":"1994-11-30","article_text":"1. Орган опеки и попечительства освобождает опекуна или попечителя от исполнения им своих обязанностей в случаях возвращения несовершеннолетнего его родителям или его усыновления.\n\nПри помещении подопечного под надзор в образовательную организацию, медицинскую организацию, организацию, оказывающую социальные услуги, или иную организацию, в том числе в организацию для детей-сирот и детей, оставшихся без попечения родителей, орган опеки и попечительства освобождает ранее назначенного опекуна или попечителя от исполнения ими своих обязанностей, если это не противоречит интересам подопечного. (В редакции Федерального закона от 24.04.2008 № 49-ФЗ)\n\n2. Опекун, попечитель могут быть освобождены от исполнения своих обязанностей по их просьбе.\n\nОпекун или попечитель может быть освобожден от исполнения своих обязанностей по инициативе органа опеки и попечительства в случае возникновения противоречий между интересами подопечного и интересами опекуна или попечителя, в том числе временно.\n\n(Пункт в редакции Федерального закона от 24.04.2008 № 49-ФЗ)\n\n3. В случаях ненадлежащего выполнения опекуном или попечителем лежащих на нем обязанностей, в том числе при использовании им опеки или попечительства в корыстных целях или при оставлении подопечного без надзора и необходимой помощи, орган опеки и попечительства может отстранить опекуна или попечителя от исполнения этих обязанностей и принять необходимые меры для привлечения виновного гражданина к установленной законом ответственности.","article_title":"Статья 39. Освобождение и отстранение опекунов и попечителей от исполнения ими своих обязанностей","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"235c2551ffdc3ed94f92b3a4a3842a1decacadea40c0ac452e077b1b2a4f8d35"},{"code_id":"GK_RF","article_number":"390","version_date":"1994-11-30","article_text":"1. Цедент отвечает перед цессионарием за недействительность переданного ему требования, но не отвечает за неисполнение этого требования должником, за исключением случая, если цедент принял на себя поручительство за должника перед цессионарием.\n\nЕсли иное не предусмотрено законом, договор, на основании которого производится уступка, может предусматривать, что цедент не несет ответственности перед цессионарием за недействительность переданного ему требования по договору, исполнение которого связано с осуществлением его сторонами предпринимательской деятельности, при условии, что такая недействительность вызвана обстоятельствами, о которых цедент не знал или не мог знать или о которых он предупредил цессионария, в том числе обстоятельствами, относящимися к дополнительным требованиям, включая требования по правам, обеспечивающим исполнение обязательства, и правам на проценты. (Дополнение абзацем - Федеральный закон от 26.07.2017 № 212-ФЗ)\n\n2. При уступке цедентом должны быть соблюдены следующие условия:\n\nуступаемое требование существует в момент уступки, если только это требование не является будущим требованием;\n\nцедент правомочен совершать уступку;\n\nуступаемое требование ранее не было уступлено цедентом другому лицу;\n\nцедент не совершал и не будет совершать никакие действия, которые могут служить основанием для возражений должника против уступленного требования.\n\nЗаконом или договором могут быть предусмотрены и иные требования, предъявляемые к уступке.\n\n3. При нарушении цедентом правил, предусмотренных пунктами 1 и 2 настоящей статьи, цессионарий вправе потребовать от цедента возврата всего переданного по соглашению об уступке, а также возмещения причиненных убытков.\n\n4. В отношениях между несколькими лицами, которым одно и то же требование передавалось от одного цедента, требование признается перешедшим к лицу, в пользу которого передача была совершена ранее.\n\nВ случае исполнения должником другому цессионарию риск последствий такого исполнения несет цедент или цессионарий, которые знали или должны были знать об уступке требования, состоявшейся ранее.","article_title":"Статья 390. Ответственность цедента","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c8de0a83efdf6e96799b0fbc9822b030d2f015bfd33da0ddc2230c4764617fe1"},{"code_id":"GK_RF","article_number":"391","version_date":"1994-11-30","article_text":"1. Перевод долга с должника на другое лицо может быть произведен по соглашению между первоначальным должником и новым должником.\n\nВ обязательствах, связанных с осуществлением их сторонами предпринимательской деятельности, перевод долга может быть произведен по соглашению между кредит\n\nором и новым должником, согласно которому новый должник принимает на себя обязательство первоначального должника.\n\n2. Перевод должником своего долга на другое лицо допускается с согласия кредитора и при отсутствии такого согласия является ничтожным.\n\nЕсли кредитор дает предварительное согласие на перевод долга, этот перевод считается состоявшимся в момент получения кредитором уведомления о переводе долга.\n\n3. При переводе долга по обязательству, связанному с осуществлением его сторонами предпринимательской деятельности, в случае, предусмотренном абзацем вторым пункта 1 настоящей статьи, первоначальный должник и новый должник несут солидарную ответственность перед кредитором, если соглашением о переводе долга не предусмотрена субсидиарная ответственность первоначального должника либо первоначальный должник не освобожден от исполнения обязательства. Первоначальный должник вправе отказаться от освобождения от исполнения обязательства.\n\nК новому должнику, исполнившему обязательство, связанное с осуществлением его сторонами предпринимательской деятельности, переходят права кредитора по этому обязательству, если иное не предусмотрено соглашением между первоначальным должником и новым должником или не вытекает из существа их отношений.\n\n4. К форме перевода долга соответственно применяются правила, содержащиеся в статье 389 настоящего Кодекса.\n\n(Статья в редакции Федерального закона от 21.12.2013 № 367-ФЗ)","article_title":"Статья 391. Условия и форма перевода долга","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"803c410c94e0c782273d52b6cb097eaa614fb1371660f047038826a2693de66b"},{"code_id":"GK_RF","article_number":"392","version_date":"1994-11-30","article_text":"Новый должник вправе выдвигать против требования кредитора возражения, основанные на отношениях между кредитором и первоначальным должником, но не вправе осуществлять в отношении кредитора право на зачет встречного требования, принадлежащего первоначальному должнику. (В редакции Федерального закона от 21.12.2013 № 367-ФЗ)","article_title":"Статья 392. Возражения нового должника против требования кредитора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6f4a0e20124df1cc8e799447136ab59796409729f8a6e00b36deaa2b89d7176b"},{"code_id":"GK_RF","article_number":"392.1","version_date":"1994-11-30","article_text":"1. Кредитор может осуществлять в отношении нового должника все права по обязательству, если иное не предусмотрено законом, договором или не вытекает из существа обязательства.\n\n2. Если при переводе долга первоначальный должник освобожден от обязательства, обеспечение исполнения обязательства, предоставленное третьим лицом, прекращается, за исключением случая, когда такое лицо согласилось отвечать за нового должника.\n\n3. Освобождение первоначального должника от обязательства распространяется на всякое предоставленное им обеспечение, если только имущество, являющееся предметом обеспечения, не передано им новому должнику.\n\n(Дополнение статьей - Федеральный закон от 21.12.2013 № 367-ФЗ)","article_title":"Статья 392.1. Права кредитора в отношении нового должника","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5d21ae8df835aae5c94bc00739c79509874abf765cbfe1f58a56039faec04db6"},{"code_id":"GK_RF","article_number":"392.2","version_date":"1994-11-30","article_text":"1. Долг может перейти с должника на другое лицо по основаниям, предусмотренным законом.\n\n2. Для перехода долга в силу закона не требуется согласие кредитора, если иное не установлено законом или не вытекает из существа обязательства.\n\n(Дополнение статьей - Федеральный закон от 21.12.2013 № 367-ФЗ)","article_title":"Статья 392.2. Переход долга в силу закона","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4c86fc0441295c8ddab4f87cbd9f2b8836eced86d65cd541c1b6b3a31fd607ed"},{"code_id":"GK_RF","article_number":"392.3","version_date":"1994-11-30","article_text":"В случае одновременной передачи стороной всех прав и обязанностей по договору другому лицу (передача договора) к сделке по передаче соответственно применяются правила об уступке требования и о переводе долга.\n\n(Дополнение статьей - Федеральный закон от 21.12.2013 № 367-ФЗ)","article_title":"Статья 392.3. Передача договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5b532dcb3c5d33a0108c495f21ac8dfa755b826b16b56484d35bee60391200a3"},{"code_id":"GK_RF","article_number":"393","version_date":"1994-11-30","article_text":"1. Должник обязан возместить кредитору убытки, причиненные неисполнением или ненадлежащим исполнением обязательства.\n\nЕсли иное не установлено законом, использование кредитором иных способов защиты нарушенных прав, предусмотренных законом или договором, не лишает его права требовать от должника возмещения убытков, причиненных неисполнением или ненадлежащим исполнением обязательства. (Дополнение абзацем - Федеральный закон от 08.03.2015 № 42-ФЗ)\n\n2. Убытки определяются в соответствии с правилами, предусмотренными статьей 15 настоящего Кодекса.\n\nВозмещение убытков в полном размере означает, что в результате их возмещения кредитор должен быть поставлен в положение, в котором он находился бы, если бы обязательство было исполнено надлежащим образом. (Дополнение абзацем - Федеральный закон от 08.03.2015 № 42-ФЗ)\n\n3. Если иное не предусмотрено законом, иными правовыми актами или договором, при определении убытков принимаются во внимание цены, существовавшие в том месте, где обязательство должно было быть исполнено, в день добровольного удовлетворения должником требования кредитора, а если требование добровольно удовлетворено не было, - в день предъявления иска. Исходя из обстоятельств, суд может удовлетворить требование о возмещении убытков, принимая во внимание цены, существующие в день вынесения решения.\n\n4. При определении упущенной выгоды учитываются предпринятые кредитором для ее получения меры и сделанные с этой целью приготовления.","article_title":"Статья 393. Обязанность должника возместить убытки","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fe8eb20b905999cf6007616845ae9e40a43b13dc6d69bd2f6fb3df7fd6c2939c"},{"code_id":"GK_RF","article_number":"393.1","version_date":"1994-11-30","article_text":"1. В случае, если неисполнение или ненадлежащее исполнение должником договора повлекло его досрочное прекращение и кредитор заключил взамен его аналогичный договор, кредитор вправе потребовать от должника возмещения убытков в виде разницы между ценой, установленной в прекращенном договоре, и ценой на сопоставимые товары, работы или услуги по условиям договора, заключенного взамен прекращенного договора.\n\n2. Если кредитор не заключил аналогичный договор взамен прекращенного договора (пункт 1 настоящей статьи), но в отношении предусмотренного прекращенным договором исполнения имеется текущая цена на сопоставимые товары, работы или услуги, кредитор вправе потребовать от должника возмещения убытков в виде разницы между ценой, установленной в прекращенном договоре, и текущей ценой.\n\nТекущей ценой признается цена, взимаемая в момент прекращения договора за сопоставимые товары, работы или услуги в месте, где должен был быть исполнен договор, а при отсутствии текущей цены в указанном месте - цена, которая применялась в другом месте и может служить разумной заменой с учетом транспортных и иных дополнительных расходов.\n\n3. Удовлетворение требований, предусмотренных пунктами 1 и 2 настоящей статьи, не освобождает сторону, не исполнившую обязательства или ненадлежаще его исполнившую, от возмещения иных убытков, причиненных другой стороне.\n\n(Дополнение статьей - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 393.1. Возмещение убытков при прекращении договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"03010b84f3909dec8d2fda8ee7bad5e8995620efc0d6bbf02a0855d177c31392"},{"code_id":"GK_RF","article_number":"394","version_date":"1994-11-30","article_text":"1. Если за неисполнение или ненадлежащее исполнение обязательства установлена неустойка, то убытки возмещаются в части, не покрытой неустойкой.\n\nЗаконом или договором могут быть предусмотрены случаи: когда допускается взыскание только неустойки, но не убытков; когда убытки могут быть взысканы в полной сумме сверх неустойки; когда по выбору кредитора могут быть взысканы либо неустойка, либо убытки.\n\n2. В случаях, когда за неисполнение или ненадлежащее исполнение обязательства установлена ограниченная ответственность (статья 400), убытки, подлежащие возмещению в части, не покрытой неустойкой, либо сверх ее, либо вместо нее, могут быть взысканы до пределов, установленных таким ограничением.","article_title":"Статья 394. Убытки и неустойка","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f4afabfb4830f0ed7e648eab7250cbb27fc226255b2e270c1c51996ddd1b8c8d"},{"code_id":"GK_RF","article_number":"396","version_date":"1994-11-30","article_text":"1. Уплата неустойки и возмещение убытков в случае ненадлежащего исполнения обязательства не освобождают должника от исполнения обязательства в натуре, если иное не предусмотрено законом или договором.\n\n2. Возмещение убытков в случае неисполнения обязательства и уплата неустойки за его неисполнение освобождают должника от исполнения обязательства в натуре, если иное не предусмотрено законом или договором.\n\n3. Отказ кредитора от принятия исполнения, которое вследствие просрочки утратило для него интерес (пункт 2 статьи 405), а также уплата неустойки, установленной в качестве отступного (статья 409), освобождают должника от исполнения обязательства в натуре.","article_title":"Статья 396. Ответственность и исполнение обязательства в натуре","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"dbe2d6a7598fbff0095936d21f74d6fac38307f0eefd569a02769368c7ac43a0"},{"code_id":"GK_RF","article_number":"397","version_date":"1994-11-30","article_text":"В случае неисполнения должником обязательства изготовить и передать вещь в собственность, в хозяйственное ведение или в оперативное управление, либо передать вещь в пользование кредитору, либо выполнить для него определенную работу или оказать ему услугу кредитор вправе в разумный срок поручить выполнение обязательства третьим лицам за разумную цену либо выполнить его своими силами, если иное не вытекает из закона, иных правовых актов, договора или существа обязательства, и потребовать от должника возмещения понесенных необходимых расходов и других убытков.","article_title":"Статья 397. Исполнение обязательства за счет должника","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"50c29b8c24badbd81f16d958cfc3c4ef7eb41bc9d4830ca4f002188444802148"},{"code_id":"GK_RF","article_number":"398","version_date":"1994-11-30","article_text":"В случае неисполнения обязательства передать индивидуально-определенную вещь в собственность, в хозяйственное ведение, в оперативное управление или в возмездное пользование кредитору последний вправе требовать отобрания этой вещи у должника и передачи ее кредитору на предусмотренных обязательством условиях. Это право отпадает, если вещь уже передана третьему лицу, имеющему право собственности, хозяйственного ведения или оперативного управления. Если вещь еще не передана, преимущество имеет тот из кредиторов, в пользу которого обязательство возникло раньше, а если это невозможно установить, - тот, кто раньше предъявил иск.\n\nВместо требования передать ему вещь, являющуюся предметом обязательства, кредитор вправе потребовать возмещения убытков.","article_title":"Статья 398. Последствия неисполнения обязательства передать индивидуально-определенную вещь","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b972be128d019f8b01bc82a3278b7ab714c20b83e7542540d7b4d2ce667229e9"},{"code_id":"GK_RF","article_number":"399","version_date":"1994-11-30","article_text":"1. До предъявления требований к лицу, которое в соответствии с законом, иными правовыми актами или условиями обязательства несет ответственность дополнительно к ответственности другого лица, являющегося основным должником (субсидиарную ответственность), кредитор должен предъявить требование к основному должнику.\n\nЕсли основной должник отказался удовлетворить требование кредитора или кредитор не получил от него в разумный срок ответ на предъявленное требование, это требование может быть предъявлено лицу, несущему субсидиарную ответственность.\n\n2. Кредитор не вправе требовать удовлетворения своего требования к основному должнику от лица, несущего субсидиарную ответственность, если это требование может быть удовлетворено путем зачета встречного требования к основному должнику либо бесспорного взыскания средств с основного должника.\n\n3. Лицо, несущее субсидиарную ответственность, должно до удовлетворения требования, предъявленного ему кредитором, предупредить об этом основного должника, а если к такому лицу предъявлен иск, - привлечь основного должника к участию в деле. В противном случае основной должник имеет право выдвинуть против регрессного требования лица, отвечающего субсидиарно, возражения, которые он имел против кредитора.","article_title":"Статья 399. Субсидиарная ответственность","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7dca2876b40533e7385ad9b683ba258523f89613c609a9abbdfd24ff43a5526c"},{"code_id":"GK_RF","article_number":"4","version_date":"1994-11-30","article_text":"1. Акты гражданского законодательства не имеют обратной силы и применяются к отношениям, возникшим после введения их в действие.\n\nДействие закона распространяется на отношения, возникшие до введения его в действие, только в случаях, когда это прямо предусмотрено законом.\n\n2. По отношениям, возникшим до введения в действие акта гражданского законодательства, он применяется к правам и обязанностям, возникшим после введения его в действие. Отношения сторон по договору, заключенному до введения в действие акта гражданского законодательства, регулируются в соответствии со статьей 422 настоящего Кодекса.","article_title":"Статья 4. Действие гражданского законодательства во времени","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"00553062b918912f8c94afb40dbf167c43f91f830e25068a0e6a35e6f4f8ed56"},{"code_id":"GK_RF","article_number":"40","version_date":"1994-11-30","article_text":"1. Опека и попечительство над совершеннолетними гражданами прекращаются в случаях вынесения судом решения о признании подопечного дееспособным или отмены ограничений его дееспособности по заявлению опекуна, попечителя или органа опеки и попечительства.\n\n2. По достижении малолетним подопечным четырнадцати лет опека над ним прекращается, а гражданин, осуществлявший обязанности опекуна, становится попечителем несовершеннолетнего без дополнительного решения об этом.\n\n3. Попечительство над несовершеннолетним прекращается без особого решения по достижении несовершеннолетним подопечным восемнадцати лет, а также при вступлении его в брак и в других случаях приобретения им полной дееспособности до достижения совершеннолетия (пункт 2 статьи 21 и статья 27).","article_title":"Статья 40. Прекращение опеки и попечительства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f6a74edf89c33d51f4b2fbd94cc5db3a4b1a7b623a36a3833b75ef4bbaf89c23"},{"code_id":"GK_RF","article_number":"400","version_date":"1994-11-30","article_text":"1. По отдельным видам обязательств и по обязательствам, связанным с определенным родом деятельности, законом может быть ограничено право на полное возмещение убытков (ограниченная ответственность).\n\n2. Соглашение об ограничении размера ответственности должника по договору присоединения или иному договору, в котором кредитором является гражданин, выступающий в качестве потребителя, ничтожно, если размер ответственности для данного вида обязательств или за данное нарушение определен законом и если соглашение заключено до наступления обстоятельств, влекущих ответственность за неисполнение или ненадлежащее исполнение обязательства.","article_title":"Статья 400. Ограничение размера ответственности по обязательствам","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2f0110d1ef6b8bd97b90642e93e20b431d3ce021ab436b1b8de46e0cf913de6f"},{"code_id":"GK_RF","article_number":"401","version_date":"1994-11-30","article_text":"1. Лицо, не исполнившее обязательства либо исполнившее его ненадлежащим образом, несет ответственность при наличии вины (умысла или неосторожности), кроме случаев, когда законом или договором предусмотрены иные основания ответственности.\n\nЛицо признается невиновным, если при той степени заботливости и осмотрительности, какая от него требовалась по характеру обязательства и условиям оборота, оно приняло все меры для надлежащего исполнения обязательства.\n\n2. Отсутствие вины доказывается лицом, нарушившим обязательство.\n\n3. Если иное не предусмотрено законом или договором, лицо, не исполнившее или ненадлежащим образом исполнившее обязательство при осуществлении предпринимательской деятельности, несет ответственность, если не докажет, что надлежащее исполнение оказалось невозможным вследствие непреодолимой силы, то есть чрезвычайных и непредотвратимых при данных условиях обстоятельств. К таким обстоятельствам не относятся, в частности, нарушение обязанностей со стороны контрагентов должника, отсутствие на рынке нужных для исполнения товаров, отсутствие у должника необходимых денежных средств.\n\n4. Заключенное заранее соглашение об устранении или ограничении ответственности за умышленное нарушение обязательства ничтожно.","article_title":"Статья 401. Основания ответственности за нарушение обязательства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1a14a93ae5f4ed7264870dea1d14160bb74e25e4076262677cdcc2429551b745"},{"code_id":"GK_RF","article_number":"402","version_date":"1994-11-30","article_text":"Действия работников должника по исполнению его обязательства считаются действиями должника. Должник отвечает за эти действия, если они повлекли неисполнение или ненадлежащее исполнение обязательства.","article_title":"Статья 402. Ответственность должника за своих работников","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2c96d538d7af459dcf76cba90b5a3abee7ad7120395c9287ba8ad01bf469a62f"},{"code_id":"GK_RF","article_number":"403","version_date":"1994-11-30","article_text":"Должник отвечает за неисполнение или ненадлежащее исполнение обязательства третьими лицами, на которых было возложено исполнение, если законом не установлено, что ответственность несет являющееся непосредственным исполнителем третье лицо.","article_title":"Статья 403. Ответственность должника за действия третьих лиц","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c73868f13f2054066b9d05c48c6e5ee1ca8a86561d55b02acedb4bd10ad31f17"},{"code_id":"GK_RF","article_number":"404","version_date":"1994-11-30","article_text":"1. Если неисполнение или ненадлежащее исполнение обязательства произошло по вине обеих сторон, суд соответственно уменьшает размер ответственности должника. Суд также вправе уменьшить размер ответственности должника, если кредитор умышленно или по неосторожности содействовал увеличению размера убытков, причиненных неисполнением или ненадлежащим исполнением, либо не принял разумных мер к их уменьшению.\n\n2. Правила пункта 1 настоящей статьи соответственно применяются и в случаях, когда должник в силу закона или договора несет ответственность за неисполнение или ненадлежащее исполнение обязательства независимо от своей вины.","article_title":"Статья 404. Вина кредитора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a10ef9ef6a854151004b76bdecae0d74d511f915c9be15eda4cdac46d7117276"},{"code_id":"GK_RF","article_number":"405","version_date":"1994-11-30","article_text":"1. Должник, просрочивший исполнение, отвечает перед кредитором за убытки, причиненные просрочкой, и за последствия случайно наступившей во время просрочки невозможности исполнения.\n\n2. Если вследствие просрочки должника исполнение утратило интерес для кредитора, он может отказаться от принятия исполнения и требовать возмещения убытков.\n\n3. Должник не считается просрочившим, пока обязательство не может быть исполнено вследствие просрочки кредитора.","article_title":"Статья 405. Просрочка должника","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bfb2cb0a5aacfb97f9e41801cde9fecf42c69d5a651ae15c8d9c144ff26d995e"},{"code_id":"GK_RF","article_number":"406","version_date":"1994-11-30","article_text":"Кредитор считается просрочившим также в случаях, указанных в пункте 2 статьи 408 настоящего Кодекса.\n\nКредитор не считается просрочившим в случае, если должник был не в состоянии исполнить обязательство, вне зависимости от того, что кредитором не были совершены действия, предусмотренные абзацем первым настоящего пункта. (Дополнение абзацем - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 406. Просрочка кредитора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"195060ff47108544746361d90bc17709bc1e66d154f13f49e166c77a91c8da3a"},{"code_id":"GK_RF","article_number":"406.1","version_date":"1994-11-30","article_text":"1. Стороны обязательства, действуя при осуществлении ими предпринимательской деятельности, могут своим соглашением предусмотреть обязанность одной стороны возместить имущественные потери другой стороны, возникшие в случае наступления определенных в таком соглашении обстоятельств и не связанные с нарушением обязательства его стороной (потери, вызванные невозможностью исполнения обязательства, предъявлением требований третьими лицами или органами государственной власти к стороне ил\n\nи к третьему лицу, указанному в соглашении, и т.п.). Соглашением сторон должен быть определен размер возмещения таких потерь или порядок его определения.\n\n2. Суд не может уменьшить размер возмещения потерь, предусмотренных настоящей статьей, за исключением случаев, если доказано, что сторона умышленно содействовала увеличению размера потерь.\n\n3. Потери, предусмотренные настоящей статьей, возмещаются независимо от признания договора незаключенным или недействительным, если иное не предусмотрено соглашением сторон.\n\n4. В случае, если потери возникли в связи с неправомерными действиями третьего лица, к стороне, возместившей такие потери, переходит требование кредитора к этому третьему лицу о возмещении убытков.\n\n5. Правила настоящей статьи применяются также в случаях, если условие о возмещении потерь предусмотрено в корпоративном договоре либо в договоре об отчуждении акций или долей в уставном капитале хозяйственного общества, стороной которого является физическое лицо.\n\n(Дополнение статьей - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 406.1. Возмещение потерь, возникших в случае наступления определенных в договоре обстоятельств","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1249ff965fe576769b0faa82af6454e22603c2309ba6521c5c2acb330f3a2210"},{"code_id":"GK_RF","article_number":"407","version_date":"1994-11-30","article_text":"1. Обязательство прекращается полностью или частично по основаниям, предусмотренным настоящим Кодексом, другими законами, иными правовыми актами или договором.\n\n2. Прекращение обязательства по требованию одной из сторон допускается только в случаях, предусмотренных законом или договором.","article_title":"Статья 407. Основания прекращения обязательств","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3f78ea45fb255e0df7080b471d69b701b89dbf6a8cdf2480a94dca6df51de2f9"},{"code_id":"GK_RF","article_number":"408","version_date":"1994-11-30","article_text":"1. Надлежащее исполнение прекращает обязательство.\n\n2. Кредитор, принимая исполнение, обязан по требованию должника выдать ему расписку в получении исполнения полностью или в соответствующей части.\n\nЕсли должник выдал кредитору в удостоверение обязательства долговой документ, то кредитор, принимая исполнение, должен вернуть этот документ, а при невозможности возвращения указать на это в выдаваемой им расписке. Расписка может быть заменена надписью на возвращаемом долговом документе. Нахождение долгового документа у должника удостоверяет, пока не доказано иное, прекращение обязательства.\n\nПри отказе кредитора выдать расписку, вернуть долговой документ или отметить в расписке невозможность его возвращения должник вправе задержать исполнение. В этих случаях кредитор считается просрочившим.","article_title":"Статья 408. Прекращение обязательства исполнением","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f13b69b6d6f125d9ec981ace4163541a426aa5281ad6ea2bcca346559e440e83"},{"code_id":"GK_RF","article_number":"409","version_date":"1994-11-30","article_text":"По соглашению сторон обязательство может быть прекращено предоставлением отступного - уплатой денежных средств или передачей иного имущества.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 409. Отступное","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"64a45c9b109f75989de8f7464cce14d3285cafd6eac927062c97acd97578fde4"},{"code_id":"GK_RF","article_number":"41","version_date":"1994-11-30","article_text":"1. Над совершеннолетним дееспособным гражданином, который по состоянию здоровья не способен самостоятельно осуществлять и защищать свои права и исполнять свои обязанност\n\nи, может быть установлен патронаж.\n\n2. В течение месяца со дня выявления совершеннолетнего дееспособного гражданина, который по состоянию здоровья не может самостоятельно осуществлять и защищать свои права и исполнять свои обязанности, ему назначается органом опеки и попечительства помощник. Помощник может быть назначен с его согласия в письменной форме, а также с согласия в письменной форме гражданина, над которым устанавливается патронаж. Работник организации, осуществляющей социальное обслуживание совершеннолетнего дееспособного гражданина, нуждающегося в установлении над ним патронажа, не может быть назначен помощником такого гражданина.\n\n3. Помощник совершеннолетнего дееспособного гражданина совершает действия в интересах гражданина, находящегося под патронажем, на основании заключаемых с этим лицом договора поручения, договора доверительного управления имуществом или иного договора.\n\n4. Орган опеки и попечительства обязан осуществлять контроль за исполнением помощником совершеннолетнего дееспособного гражданина своих обязанностей и извещать находящегося под патронажем гражданина о нарушениях, допущенных его помощником и являющихся основанием для расторжения заключенных между ними договора поручения, договора доверительного управления имуществом или иного договора.\n\n5. Патронаж над совершеннолетним дееспособным гражданином, установленный в соответствии с пунктом 1 настоящей статьи, прекращается в связи с прекращением договора поручения, договора доверительного управления имуществом или иного договора по основаниям, предусмотренным законом или договором.\n\n(Статья в редакции Федерального закона от 24.04.2008 № 49-ФЗ)","article_title":"Статья 41. Патронаж над совершеннолетними дееспособными гражданами","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"71e37841600fd07fc76358c4f2e34ed79d43df43fc81729df352a6492bae627f"},{"code_id":"GK_RF","article_number":"410","version_date":"1994-11-30","article_text":"Обязательство прекращается полностью или частично зачетом встречного однородного требования, срок которого наступил либо срок которого не указан или определен моментом востребования. В случаях, предусмотренных законом, допускается зачет встречного однородного требования, срок которого не наступил. Для зачета достаточно заявления одной стороны. (В редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 410. Прекращение обязательства зачетом","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b849abaa9011bb4b0b34da05d28ff59c1d20f876fd40e6fc9dfdfa1558fb0730"},{"code_id":"GK_RF","article_number":"411","version_date":"1994-11-30","article_text":"Не допускается зачет требований:\n\nо возмещении вреда, причиненного жизни или здоровью;\n\nо пожизненном содержании;\n\nо взыскании алиментов;\n\nпо которым истек срок исковой давности;\n\nв иных случаях, предусмотренных законом или договором.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 411. Случаи недопустимости зачета","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"27c5798a044923da7997182422562f48df0a171d5286b4cc729c3d5802e0b4ae"},{"code_id":"GK_RF","article_number":"412","version_date":"1994-11-30","article_text":"В случае уступки требования должник вправе зачесть против требования нового кредитора свое встречное требование к первоначальному кредитору.\n\nЗачет производится, если требование возникло по основанию, существовавшему к моменту получения должником уведомления об уступке требования, и срок требования наступил до его получения либо этот срок не указан или определен моментом востребования.","article_title":"Статья 412. Зачет при уступке требования","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c4f32c89a932ee7f21f2fad467a02dcac0cb11e7faf29c82d36cd2893d652e26"},{"code_id":"GK_RF","article_number":"413","version_date":"1994-11-30","article_text":"Обязательство прекращается совпадением должника и кредитора в одном лице, если иное не установлено законом или не вытекает из существа обязательства. (В редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 413. Прекращение обязательства совпадением должника и кредитора в одном лице","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b10af3e9215cb754ad2662574b441e7eb476e11b4dcf1319b87b22c6f972d45c"},{"code_id":"GK_RF","article_number":"414","version_date":"1994-11-30","article_text":"1. Обязательство прекращается соглашением сторон о замене первоначального обязательства, существовавшего между ними, другим обязательством между теми же лицами (новация), если иное не установлено законом или не вытекает из существа отношений.\n\n2. Новация прекращает дополнительные обязательства, связанные с первоначальным обязательством, если иное не предусмотрено соглашением сторон.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 414. Прекращение обязательства новацией","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2d5d22aeddc7c3eb989fa8a1462ed3b2e1e8f8ffc3da59945783aa379bb22d30"},{"code_id":"GK_RF","article_number":"417","version_date":"1994-11-30","article_text":"1. Если в результате издания акта органа государственной власти или органа местного самоуправления исполнение обязательства становится невозможным полностью или частично, обязательство прекращается полностью или в соответствующей части. Стороны, понесшие в результате этого убытки, вправе требовать их возмещения в соответствии со статьями 13 и 16 настоящего Кодекса.\n\n2. Обязательство не считается прекращенным, если издание акта органа государственной власти или органа местного самоуправления, повлекшее невозможность исполнения обязательства, вызвано неправомерными действиями (бездействием) самого должника.\n\n3. В случае признания недействительным либо отмены в установленном порядке акта органа государственной власти или органа местного самоуправления (пункт 1 настоящей статьи) обязательство не считается прекращенным, если иное не вытекает из соглашения сторон или существа обязательства либо если кредитор в разумный срок не отказался от исполнения обязательства.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 417. Прекращение обязательства на основании акта органа государственной власти или органа местного самоуправления","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3e4721833d9d2196d02970b53c9d4547979cdb16e7ab12568cb93de7d43e56e3"},{"code_id":"GK_RF","article_number":"418","version_date":"1994-11-30","article_text":"1. Обязательство прекращается смертью должника, если исполнение не может быть произведено без личного участия должника либо обязательство иным образом неразрывно связано с личностью должника.\n\n2. Обязательство прекращается смертью кредитора, если исполнение предназначено лично для кредитора либо обязательство иным образом неразрывно связано с личностью кредитора.","article_title":"Статья 418. Прекращение обязательства смертью гражданина","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2f7d29e5af0ba9aef551a50d62ac2f91e33a3520011cd47f2e8a25353e30b213"},{"code_id":"GK_RF","article_number":"419","version_date":"1994-11-30","article_text":"Обязательство прекращается ликвидацией юридического лица (должника или кредитора), кроме случаев, когда законом или иными правовыми актами исполнение обязательства ликвидированного юридического лица возлагается на другое лицо (по требованиям о возмещении вреда, причиненного жизни или здоровью, и др.).","article_title":"Статья 419. Прекращение обязательства ликвидацией юридического лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"37f3188a4d00ff9c36c3cf7ecdf708e7c27b95f2ea526fa32bd2a2c394ea4594"},{"code_id":"GK_RF","article_number":"42","version_date":"1994-11-30","article_text":"Гражданин может быть по заявлению заинтересованных лиц признан судом безвестно отсутствующим, если в течение года в месте его жительства нет сведений о месте его пребывания.\n\nПри невозможности установить день получения последних сведений об отсутствующем началом исчисления срока для признания безвестного отсутствия считается первое число месяца, следующего за тем, в котором были получены последние сведения об отсутствующем, а при невозможности установить этот месяц - первое января следующего года.","article_title":"Статья 42. Признание гражданина безвестно отсутствующим","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b06573fcb41f028f4420b44052aeb2e0b2dab43ae016ca118657dbc5525336bf"},{"code_id":"GK_RF","article_number":"420","version_date":"1994-11-30","article_text":"1. Договором признается соглашение двух или нескольких лиц об установлении, изменении или прекращении гражданских прав и обязанностей.","article_title":"Статья 420. Понятие договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9154ba2ce1e84141998e6acf8753eb919ea43eae2d2cf318672efb856e27e346"},{"code_id":"GK_RF","article_number":"421","version_date":"1994-11-30","article_text":"1. Граждане и юридические лица свободны в заключении договора.\n\nПонуждение к заключению договора не допускается, за исключением случаев, когда обязанность заключить договор предусмотрена настоящим Кодексом, законом или добровольно принятым обязательством.\n\nВ случаях, когда условие договора предусмотрено нормой, которая применяется постольку, поскольку соглашением сторон не установлено иное (диспозитивная норма), стороны могут своим соглашением исключить ее применение либо установить условие, отличное от предусмотренного в ней. При отсутствии такого соглашения условие договора определяется диспозитивной нормой.","article_title":"Статья 421. Свобода договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0a871b43e66339eba4073220e4dbf1d9a0b0cba96552558b7b6118199ced1a59"},{"code_id":"GK_RF","article_number":"422","version_date":"1994-11-30","article_text":"1. Договор должен соответствовать обязательным для сторон правилам, установленным законом и иными правовыми актами (императивным нормам), действующим в момент его заключения.\n\n2. Если после заключения договора принят закон, устанавливающий обязательные для сторон правила иные, чем те, которые действовали при заключении договора, условия заключенного договора сохраняют силу, кроме случаев, когда в законе установлено, что его действие распространяется на отношения, возникшие из ранее заключенных договоров.","article_title":"Статья 422. Договор и закон","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b353b75c9b83016593adc24237aff481545575142f6071852b79ec93540de00d"},{"code_id":"GK_RF","article_number":"423","version_date":"1994-11-30","article_text":"1. Договор, по которому сторона должна получить плату или иное встречное предоставление за исполнение своих обязанностей, является возмездным.\n\n2. Безвозмездным признается договор, по которому одна сторона обязуется предоставить что-либо другой стороне без получения от нее платы или иного встречного предоставления.\n\n3. Договор предполагается возмездным, если из закона, иных правовых актов, содержания или существа договора не вытекает иное.","article_title":"Статья 423. Возмездный и безвозмездный договоры","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0f67a7acb24c47fb42af64db2f0858979327104c7586bd75ab73b038159ad0a0"},{"code_id":"GK_RF","article_number":"424","version_date":"1994-11-30","article_text":"1. Исполнение договора оплачивается по цене, установленной соглашением сторон.\n\nВ предусмотренных законом случаях применяются цены (тарифы, расценки, ставки и т.п.), устанавливаемые или регулируемые уполномоченными на то государственными органами и (или) органами местного самоуправления. (В редакции Федерального закона от 29.06.2009 № 132-ФЗ)\n\n2. Изменение цены после заключения договора допускается в случаях и на условиях, предусмотренных договором, законом либо в установленном законом порядке.\n\n3. В случаях, когда в возмездном договоре цена не предусмотрена и не может быть определена исходя из условий договора, исполнение договора должно быть оплачено по цене, которая при сравнимых обстоятельствах обычно взимается за аналогичные товары, работы или услуги.","article_title":"Статья 424. Цена","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3ff1ffc61d46a120835f4cf1ff9580ff4d9d073e3df42a303e7f50fb05d7e0b2"},{"code_id":"GK_RF","article_number":"425","version_date":"1994-11-30","article_text":"1. Договор вступает в силу и становится обязательным для сторон с момента его заключения.\n\nДоговор, в котором отсутствует такое условие, признается действующим до определенного в нем момента окончания исполнения сторонами обязательства.","article_title":"Статья 425. Действие договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"acb77375a97847e77add997682a4c2bb3974cb77ca181604287761e2d467e084"},{"code_id":"GK_RF","article_number":"426","version_date":"1994-11-30","article_text":"1. Публичным договором признается договор, заключенный лицом, осуществляющим предпринимательскую или иную приносящую доход деятельность, и устанавливающий его обязанности по продаже товаров, выполнению работ либо оказанию услуг, которые такое лицо по характеру своей деятельности должно осуществлять в отношении каждого, кто к нему обратится (розничная торговля, перевозка транспортом общего пользования, услуги связи, энергоснабжение, медицинское, гостиничное обслуживание и т.п.).\n\nЛицо, осуществляющее предпринимательскую или иную приносящую доход деятельность, не вправе оказывать предпочтение одному лицу перед другим лицом в отношении заключения публичного договора, за исключением случаев, предусмотренных законом или иными правовыми актами.\n\n(Пункт в редакции Федерального закона от 08.03.2015 № 42-ФЗ)\n\nПри необоснованном уклонении лица, осуществляющего предпринимательскую или иную приносящую доход деятельность, от заключения публичного договора применяются положения, предусмотренные пунктом 4 статьи 445 настоящего Кодекса.  (В редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 426. Публичный договор","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"83a35aea5cba90b22b4695e8c11457b01dd857aab81e3be52c7934c79867cd2f"},{"code_id":"GK_RF","article_number":"427","version_date":"1994-11-30","article_text":"1. В договоре может быть предусмотрено, что его отдельные условия определяются примерными условиями, разработанными для договоров соответствующего вида и опубликованными в печати.","article_title":"Статья 427. Примерные условия договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e6c6b95e96803425fc94205471702ba7bc08d1f8d9849a729948ec1bd0870fc8"},{"code_id":"GK_RF","article_number":"428","version_date":"1994-11-30","article_text":"1. Договором присоединения признается договор, условия которого определены одной из сторон в формулярах или иных стандартных формах и могли быть приняты другой стороной не иначе как путем присоединения к предложенному договору в целом.\n\n2. Присоединившаяся к договору сторона вправе потребовать расторжения или изменения договора, если договор присоединения хотя и не противоречит закону и иным правовым актам, но лишает эту сторону прав, обычно предоставляемых по договорам такого вида, исключает или ограничивает ответственность другой стороны за нарушение обязательств либо содержит другие явно обременительные для присоединившейся стороны условия, которые она исходя из своих разумно понимаемых интересов не приняла бы при наличии у нее возможности участвовать в определении условий договора.\n\nЕсли иное не установлено законом или не вытекает из существа обязательства, в случае изменения или расторжения договора судом по требованию присоединившейся к договору стороны договор считается действовавшим в измененной редакции либо соответственно не действовавшим с момента его заключения. (Дополнение абзацем - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 428. Договор присоединения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"eccc50e62e1a27952c09723b5c6cdfaaf9623e5b948e256bd139b16082b3e27d"},{"code_id":"GK_RF","article_number":"429","version_date":"1994-11-30","article_text":"1. По предварительному договору стороны обязуются заключить в будущем договор о передаче имущества, выполнении работ или оказании услуг (основной договор) на условиях, предусмотренных предварительным договором.\n\n2. Предварительный договор заключается в форме, установленной для основного договора, а если форма основного договора не установлена, то в письменной форме. Несоблюдение правил о форме предварительного договора влечет его ничтожность.\n\nЕсли такой срок в предварительном договоре не определен, основной договор подлежит заключению в течение года с момента заключения предварительного договора.\n\nименяются положения, предусмотренные пунктом 4 статьи 445 настоящего Кодекса. Требование о понуждении к заключению основного договора может быть заявлено в течение шести месяцев с момента неисполнения обязательства по заключению договора.\n\nВ случае возникновения разногласий сторон относительно условий основного договора такие условия определяются в соответствии с решением суда. Основной договор в этом случае считается заключенным с момента вступления в законную силу решения суда или с момента, указанного в решении суда.\n\n(Пункт в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 429. Предварительный договор","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3c101ebfe2de8bee587152b94abe72a2d38422c00764c2e9e3d89fdd482f7a18"},{"code_id":"GK_RF","article_number":"429.1","version_date":"1994-11-30","article_text":"1. Рамочным договором (договором с открытыми условиями) признается договор, определяющий общие условия обязательственных взаимоотношений сторон, которые могут быть конкретизированы и уточнены сторонами путем заключения отдельных договоров, подачи заявок одной из сторон или иным образом на основании либо во исполнение рамочного договора.\n\n2. К отношениям сторон, не урегулированным отдельными договорами, в том числе в случае незаключения сторонами отдельных договоров, подлежат применению общие условия, содержащиеся в рамочном договоре, если иное не указано в отдельных договорах или не вытекает из существа обязательства.\n\n(Дополнение статьей - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 429.1. Рамочный договор","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"776526e44ff1a0c08f11198566997a81384fd33834b7e9f31880371c2d05a8c2"},{"code_id":"GK_RF","article_number":"429.2","version_date":"1994-11-30","article_text":"1. В силу соглашения о предоставлении опциона на заключение договора (опцион на заключение договора) одна сторона посредством безотзывной оферты предоставляет другой стороне право заключить один или несколько договоров на условиях, предусмотренных опционом. Опцион на заключение договора предоставляется за плату или другое встречное предоставление, если иное не предусмотрено соглашением, в том числе заключенным между коммерческими организациями. Другая сторона вправе заключить договор путем акцепта такой оферты в порядке, в сроки и на условиях, которые предусмотрены опционом.\n\nОпционом на заключение договора может быть предусмотрено, что акцепт возможен только при наступлении определенного таким опционом условия, в том числе зависящего от воли одной из сторон.\n\n2. В случае, когда опционом на заключение договора срок для акцепта безотзывной оферты не установлен, этот срок считается равным одному году, если иное не вытекает из существа договора или обычаев.\n\n3. Если опционом на заключение договора не предусмотрено иное, платеж по нему не засчитывается в счет платежей по договору, заключаемому на основании безотзывной оферты, и не подлежит возврату в случае, когда не будет акцепта.\n\n4. Опцион на заключение договора должен содержать условия, позволяющие определить предмет и другие существенные условия договора, подлежащего заключению.\n\nПредмет договора, подлежащего заключению, может быть описан любым способом, позволяющим его идентифицировать на момент акцепта безотзывной оферты.\n\n5. Опцион на заключение договора заключается в форме, установленной для договора, подлежащего заключению.\n\n6. Опцион на заключение договора может быть включен в другое соглашение, если иное не вытекает из существа такого соглашения.\n\n7. Права по опциону на заключение договора могут быть уступлены другому лицу, если иное не предусмотрено этим соглашением или не вытекает из его существа.\n\n8. Особенности отдельных видов опционов на заключение договора могут быть установлены законом.\n\n(Дополнение статьей - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 429.2. Опцион на заключение договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2e0a6e6260735f9f7cc1929ddca5685f3d411b66dae489fffee0aa3b2aa4d37d"}]$law7d0026$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j
on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
commit;
